#ifndef RTSA_MARKER_CARD_H
#define RTSA_MARKER_CARD_H

#include "MarkerEngine.h"
#include <QWidget>
#include <QLabel>
#include <QPoint>

namespace rtsa {

/// Draggable floating card widget for displaying active Marker details.
class MarkerCard : public QWidget {
    Q_OBJECT

public:
    explicit MarkerCard(QWidget* parent = nullptr);

    /// Update marker rows from MarkerEngine
    void updateMarkers(const MarkerEngine* engine);

protected:
    void mousePressEvent(QMouseEvent* event) override;
    void mouseMoveEvent(QMouseEvent* event) override;
    void mouseReleaseEvent(QMouseEvent* event) override;

private:
    QString formatFrequency(double hz) const;

    QWidget* m_contentWidget;
    QPoint m_dragPosition;
    bool m_isDragging = false;
};

} // namespace rtsa

#endif // RTSA_MARKER_CARD_H

#include "MarkerCard.h"
#include <QVBoxLayout>
#include <QHBoxLayout>
#include <QMouseEvent>
#include <QGraphicsDropShadowEffect>
#include <algorithm>

namespace rtsa {

static const QString kCardStyleSheet = R"(
    QWidget#MarkerCard {
        background-color: rgba(18, 18, 36, 235);
        border: 1px solid #4488ff;
        border-radius: 6px;
    }
    QLabel#CardHeader {
        color: #00e5ff;
        font-family: Consolas, monospace;
        font-size: 10px;
        font-weight: bold;
        padding: 4px 6px;
        background-color: rgba(30, 30, 54, 200);
        border-top-left-radius: 5px;
        border-top-right-radius: 5px;
    }
    QLabel#TableHeader {
        color: #4488ff;
        font-family: Consolas, monospace;
        font-size: 9px;
        font-weight: bold;
        padding-bottom: 2px;
    }
    QLabel.DataCell {
        font-family: Consolas, monospace;
        font-size: 10px;
        font-weight: bold;
    }
)";

MarkerCard::MarkerCard(QWidget* parent)
    : QWidget(parent)
{
    setObjectName("MarkerCard");
    setStyleSheet(kCardStyleSheet);
    setCursor(Qt::SizeAllCursor); // Indicate draggable

    // Shadow effect
    auto* shadow = new QGraphicsDropShadowEffect(this);
    shadow->setBlurRadius(15);
    shadow->setColor(QColor(0, 0, 0, 180));
    shadow->setOffset(0, 4);
    setGraphicsEffect(shadow);

    auto* mainLayout = new QVBoxLayout(this);
    mainLayout->setContentsMargins(0, 0, 0, 6);
    mainLayout->setSpacing(4);

    // Card Header (Title bar)
    auto* headerLabel = new QLabel(":: MARKER DATA (DRAGGABLE)", this);
    headerLabel->setObjectName("CardHeader");
    mainLayout->addWidget(headerLabel);

    // Table Header
    auto* tableHeader = new QWidget(this);
    auto* thLayout = new QHBoxLayout(tableHeader);
    thLayout->setContentsMargins(8, 2, 8, 2);
    thLayout->setSpacing(6);

    auto* lblMkr  = new QLabel("MKR", tableHeader);
    auto* lblFreq = new QLabel("FREQUENCY", tableHeader);
    auto* lblAmp  = new QLabel("AMPLITUDE", tableHeader);
    auto* lblDelta= new QLabel("DELTA / REF", tableHeader);

    lblMkr->setObjectName("TableHeader");
    lblFreq->setObjectName("TableHeader");
    lblAmp->setObjectName("TableHeader");
    lblDelta->setObjectName("TableHeader");

    lblMkr->setFixedWidth(40);
    lblFreq->setFixedWidth(95);
    lblAmp->setFixedWidth(75);

    thLayout->addWidget(lblMkr);
    thLayout->addWidget(lblFreq);
    thLayout->addWidget(lblAmp);
    thLayout->addWidget(lblDelta, 1);

    mainLayout->addWidget(tableHeader);

    // Content container for rows
    m_contentWidget = new QWidget(this);
    auto* contentLayout = new QVBoxLayout(m_contentWidget);
    contentLayout->setContentsMargins(8, 0, 8, 0);
    contentLayout->setSpacing(2);

    mainLayout->addWidget(m_contentWidget);

    setMinimumWidth(360);
    hide(); // Hidden until markers are active
}

void MarkerCard::updateMarkers(const MarkerEngine* engine)
{
    if (!engine) {
        hide();
        return;
    }

    // Clear existing row widgets
    QLayout* layout = m_contentWidget->layout();
    QLayoutItem* item;
    while ((item = layout->takeAt(0)) != nullptr) {
        delete item->widget();
        delete item;
    }

    int activeCount = 0;

    for (const auto& m : engine->allMarkers()) {
        if (!m.active) continue;
        activeCount++;

        auto* rowWidget = new QWidget(m_contentWidget);
        auto* rowLayout = new QHBoxLayout(rowWidget);
        rowLayout->setContentsMargins(0, 1, 0, 1);
        rowLayout->setSpacing(6);

        auto* lblId   = new QLabel(QString("M%1").arg(m.id), rowWidget);
        auto* lblFreq = new QLabel(formatFrequency(m.freqHz), rowWidget);
        auto* lblAmp  = new QLabel(QString("%1 dBm").arg(m.amplitude, 0, 'f', 1), rowWidget);
        auto* lblDelta= new QLabel("--", rowWidget);

        lblId->setFixedWidth(40);
        lblFreq->setFixedWidth(95);
        lblAmp->setFixedWidth(75);

        // Colorize row text using Marker's color
        QString colorHex = m.color.name();
        QString cellStyle = QString("color: %1; font-family: Consolas; font-size: 10px; font-weight: bold;").arg(colorHex);

        lblId->setStyleSheet(cellStyle);
        lblFreq->setStyleSheet(cellStyle);
        lblAmp->setStyleSheet(cellStyle);
        lblDelta->setStyleSheet(cellStyle);

        if (m.isDelta) {
            int refId = (m.refMarkerId >= 1) ? m.refMarkerId : 1;
            lblDelta->setText(QString("Δ(M%1-M%2): %3, %4 dB")
                                  .arg(m.id)
                                  .arg(refId)
                                  .arg(formatFrequency(m.deltaFreqHz))
                                  .arg(m.deltaAmplitude, 0, 'f', 1));
        }

        rowLayout->addWidget(lblId);
        rowLayout->addWidget(lblFreq);
        rowLayout->addWidget(lblAmp);
        rowLayout->addWidget(lblDelta, 1);

        layout->addWidget(rowWidget);
    }

    adjustSize();

    if (activeCount > 0) {
        if (isHidden()) {
            show();
            // Default position top-right of parent
            if (parentWidget()) {
                move(parentWidget()->width() - width() - 25, 45);
            }
        }
    } else {
        hide();
    }
}

// ── Mouse Dragging ──

void MarkerCard::mousePressEvent(QMouseEvent* event)
{
    if (event->button() == Qt::LeftButton) {
        m_isDragging = true;
        m_dragPosition = event->globalPosition().toPoint() - frameGeometry().topLeft();
        event->accept();
    }
}

void MarkerCard::mouseMoveEvent(QMouseEvent* event)
{
    if (m_isDragging && (event->buttons() & Qt::LeftButton)) {
        QPoint newPos = event->globalPosition().toPoint() - m_dragPosition;

        // Clamp inside parent geometry
        if (parentWidget()) {
            int maxX = parentWidget()->width() - width();
            int maxY = parentWidget()->height() - height();
            newPos.setX(std::clamp(newPos.x(), 0, std::max(0, maxX)));
            newPos.setY(std::clamp(newPos.y(), 0, std::max(0, maxY)));
        }

        move(newPos);
        event->accept();
    }
}

void MarkerCard::mouseReleaseEvent(QMouseEvent* event)
{
    if (event->button() == Qt::LeftButton) {
        m_isDragging = false;
        event->accept();
    }
}

QString MarkerCard::formatFrequency(double hz) const
{
    double absHz = std::abs(hz);
    QString prefix = (hz < 0) ? "-" : "";

    if (absHz >= 1e9)
        return QString("%1%2 G").arg(prefix).arg(absHz / 1e9, 0, 'f', 3);
    if (absHz >= 1e6)
        return QString("%1%2 M").arg(prefix).arg(absHz / 1e6, 0, 'f', 2);
    if (absHz >= 1e3)
        return QString("%1%2 k").arg(prefix).arg(absHz / 1e3, 0, 'f', 1);
    return QString("%1%2 Hz").arg(prefix).arg(absHz, 0, 'f', 0);
}

} // namespace rtsa

