// ── Mouse Drag & Wheel Shortcuts ──

void SpectrumPlot::wheelEvent(QWheelEvent* event)
{
    int delta = event->angleDelta().y();
    if (delta == 0) return;

    double factor = (delta > 0) ? 0.85 : 1.18;
    double newSpan = std::clamp(m_span * factor, 1.0e6, 1000.0e6);

    if (std::abs(newSpan - m_span) > 1e3) {
        setSpan(newSpan);
        emit spanUserChanged(newSpan);
        event->accept();
    }
}

void SpectrumPlot::mousePressEvent(QMouseEvent* event)
{
    if (event->button() == Qt::LeftButton) {
        QRect area = plotArea();
        if (area.contains(event->pos())) {
            m_isPlotDragging = true;
            m_dragStartPos = event->pos();
            m_dragStartCenterFreq = m_centerFreq;
            m_dragStartRefLevel   = m_refLevel;
            setCursor(Qt::ClosedHandCursor);
            event->accept();
        }
    }
}

void SpectrumPlot::mouseMoveEvent(QMouseEvent* event)
{
    if (m_isPlotDragging && (event->buttons() & Qt::LeftButton)) {
        QRect area = plotArea();
        if (area.width() <= 0 || area.height() <= 0) return;

        int dx = event->pos().x() - m_dragStartPos.x();
        int dy = event->pos().y() - m_dragStartPos.y();

        // Horizontal Drag -> Shift Center Frequency
        double freqPerPixel = m_span / static_cast<double>(area.width());
        double newCenterFreq = std::clamp(m_dragStartCenterFreq - dx * freqPerPixel, 10.0e6, 6000.0e6);

        // Vertical Drag -> Shift Ref Level
        double dbPerPixel = (m_dbPerDiv * kGridDivY) / static_cast<double>(area.height());
        double newRefLevel = std::clamp(m_dragStartRefLevel + dy * dbPerPixel, -120.0, 30.0);

        bool changed = false;
        if (std::abs(newCenterFreq - m_centerFreq) > 10.0) {
            setCenterFreq(newCenterFreq);
            emit centerFreqUserChanged(newCenterFreq);
            changed = true;
        }

        if (std::abs(newRefLevel - m_refLevel) > 0.1) {
            setRefLevel(newRefLevel);
            emit refLevelUserChanged(newRefLevel);
            changed = true;
        }

        if (changed) {
            event->accept();
        }
    }
}

void SpectrumPlot::mouseReleaseEvent(QMouseEvent* event)
{
    if (event->button() == Qt::LeftButton && m_isPlotDragging) {
        m_isPlotDragging = false;
        setCursor(Qt::ArrowCursor);
        event->accept();
    }
}

QRect SpectrumPlot::plotArea() const
{
    return QRect(kMarginLeft, kMarginTop,
                 width() - kMarginLeft - kMarginRight,
                 height() - kMarginTop - kMarginBottom);
}

QString SpectrumPlot::formatFrequency(double hz) const
{
    if (hz >= 1e9)
        return QString("%1 G").arg(hz / 1e9, 0, 'f', 3);
    if (hz >= 1e6)
        return QString("%1 M").arg(hz / 1e6, 0, 'f', 2);
    if (hz >= 1e3)
        return QString("%1 k").arg(hz / 1e3, 0, 'f', 1);
    return QString("%1 Hz").arg(hz, 0, 'f', 0);
}

} // namespace rtsa

