void SpectrumPlot::rebuildGridCache()
{
    m_gridCache = QPixmap(size());
    m_gridCache.fill(QColor(0x0e, 0x10, 0x1c)); // Deep industrial navy background

    QPainter painter(&m_gridCache);
    painter.setRenderHint(QPainter::Antialiasing, true);
    painter.setRenderHint(QPainter::TextAntialiasing, true);

    const QRect area = plotArea();

    // ── Industrial Grid Lines ──
    QColor colorGridMinor(0x1e, 0x28, 0x3c);
    QColor colorGridMajor(0x3a, 0x50, 0x70);

    // Vertical grid lines
    for (int i = 0; i <= kGridDivX; ++i) {
        int x = area.left() + (area.width() * i) / kGridDivX;
        painter.setPen(QPen(i == kGridDivX / 2 ? colorGridMajor : colorGridMinor, 1, i == kGridDivX / 2 ? Qt::SolidLine : Qt::DashLine));
        painter.drawLine(x, area.top(), x, area.bottom());

        // X-axis tick mark (5px)
        painter.setPen(QPen(QColor(0x44, 0x88, 0xff), 1));
        painter.drawLine(x, area.bottom(), x, area.bottom() + 5);
    }

    // Horizontal grid lines
    for (int i = 0; i <= kGridDivY; ++i) {
        int y = area.top() + (area.height() * i) / kGridDivY;
        painter.setPen(QPen(i == kGridDivY / 2 ? colorGridMajor : colorGridMinor, 1, i == kGridDivY / 2 ? Qt::SolidLine : Qt::DashLine));
        painter.drawLine(area.left(), y, area.right(), y);

        // Y-axis tick mark (5px)
        painter.setPen(QPen(QColor(0x44, 0x88, 0xff), 1));
        painter.drawLine(area.left() - 5, y, area.left(), y);
    }

    // Outer plot border box
    painter.setPen(QPen(QColor(0x44, 0x88, 0xff), 1));
    painter.drawRect(area);

    // ── Y-Axis Labels (Amplitude dBm) ──
    painter.setFont(QFont("Consolas", 10, QFont::Bold));
    painter.setPen(QColor(0x00, 0xff, 0x88)); // Industrial bright green

    for (int i = 0; i <= kGridDivY; ++i) {
        int y = area.top() + (area.height() * i) / kGridDivY;
        double dBm = m_refLevel - i * m_dbPerDiv;
        QString label = QString("%1").arg(dBm, 0, 'f', 0);
        QRect textRect(2, y - 9, kMarginLeft - 10, 18);
        painter.drawText(textRect, Qt::AlignRight | Qt::AlignVCenter, label);
    }

    // Y-Axis Unit Header
    painter.setFont(QFont("Consolas", 10, QFont::Bold));
    painter.setPen(QColor(0x00, 0xe5, 0xff)); // Cyan
    painter.drawText(QRect(2, area.top() - 20, kMarginLeft - 10, 18),
                     Qt::AlignRight | Qt::AlignBottom, "dBm");

    // ── X-Axis Labels (Frequency) ──
    painter.setFont(QFont("Consolas", 10, QFont::Bold));
    painter.setPen(QColor(0xee, 0xee, 0xff)); // High contrast readable white

    double startFreq = m_centerFreq - m_span / 2.0;
    double freqStep  = m_span / kGridDivX;

    for (int i = 0; i <= kGridDivX; ++i) {
        int x = area.left() + (area.width() * i) / kGridDivX;
        double freq = startFreq + i * freqStep;
        QString label = formatFrequency(freq);

        int align = Qt::AlignHCenter;
        if (i == 0) align = Qt::AlignLeft;
        else if (i == kGridDivX) align = Qt::AlignRight;

        QRect textRect(x - 50, area.bottom() + 8, 100, 20);
        painter.drawText(textRect, align | Qt::AlignTop, label);
    }

    // X-Axis Sub-label (Center & Span)
    painter.setFont(QFont("Consolas", 10, QFont::Bold));
    painter.setPen(QColor(0x00, 0xe5, 0xff));
    QString axisSubText = QString("CENTER: %1   |   SPAN: %2")
                              .arg(formatFrequency(m_centerFreq))
                              .arg(formatFrequency(m_span));
    painter.drawText(QRect(area.left(), area.bottom() + 28, area.width(), 18),
                     Qt::AlignCenter, axisSubText);
}

// ── Info bar ──

void SpectrumPlot::drawInfoBar(QPainter& painter)
{
    const QRect area = plotArea();

    painter.fillRect(area.left(), area.top(), area.width(), 24, QColor(0x16, 0x18, 0x2e));

    painter.setPen(QColor(0x00, 0xe5, 0xff));
    QFont infoFont("Consolas", 10, QFont::Bold);
    painter.setFont(infoFont);

    int x = area.left() + 10;
    int y = area.top() + 3;
    int spacing = area.width() / 5;

    painter.drawText(x, y, spacing, 18, Qt::AlignLeft | Qt::AlignVCenter,
                     QString("CF: %1").arg(formatFrequency(m_centerFreq)));

    painter.drawText(x + spacing, y, spacing, 18, Qt::AlignLeft | Qt::AlignVCenter,
                     QString("Span: %1").arg(formatFrequency(m_span)));

    painter.drawText(x + spacing * 2, y, spacing, 18, Qt::AlignLeft | Qt::AlignVCenter,
                     QString("Ref: %1 dBm").arg(m_refLevel, 0, 'f', 1));

    painter.drawText(x + spacing * 3, y, spacing, 18, Qt::AlignLeft | Qt::AlignVCenter,
                     QString("%1 dB/div").arg(m_dbPerDiv, 0, 'f', 0));

    // Live stats
    painter.setPen(QColor(0x88, 0xaa, 0xcc));
    painter.drawText(x + spacing * 4 - 10, y, spacing + 10, 18, Qt::AlignRight | Qt::AlignVCenter,
                     QString("%1 FPS | F#%2 D%3").arg(m_currentFps, 0, 'f', 1).arg(m_frameId).arg(m_dropCount));
}

