void SpectrumPlot::rebuildGridCache()
{
    m_gridCache = QPixmap(size());
    m_gridCache.fill(kColorBackground);

    QPainter painter(&m_gridCache);
    painter.setRenderHint(QPainter::Antialiasing, true);

    const QRect area = plotArea();

    // Vertical grid lines
    for (int i = 0; i <= kGridDivX; ++i) {
        int x = area.left() + (area.width() * i) / kGridDivX;
        painter.setPen(QPen(i == kGridDivX / 2 ? kColorGridMajor : kColorGrid, 1));
        painter.drawLine(x, area.top(), x, area.bottom());
    }

    // Horizontal grid lines
    for (int i = 0; i <= kGridDivY; ++i) {
        int y = area.top() + (area.height() * i) / kGridDivY;
        painter.setPen(QPen(i == 0 ? kColorGridMajor : kColorGrid, 1));
        painter.drawLine(area.left(), y, area.right(), y);
    }

    // Plot border
    painter.setPen(QPen(kColorGridMajor, 1));
    painter.drawRect(area);

    // X-axis labels (frequency)
    painter.setPen(kColorText);
    QFont labelFont("Consolas", 8);
    painter.setFont(labelFont);

    double startFreq = m_centerFreq - m_span / 2.0;
    double freqStep = m_span / kGridDivX;

    for (int i = 0; i <= kGridDivX; ++i) {
        int x = area.left() + (area.width() * i) / kGridDivX;
        double freq = startFreq + i * freqStep;
        QString label = formatFrequency(freq);
        QRect textRect(x - 40, area.bottom() + 4, 80, 16);
        painter.drawText(textRect, Qt::AlignHCenter | Qt::AlignTop, label);
    }

    // Y-axis labels (amplitude)
    for (int i = 0; i <= kGridDivY; ++i) {
        int y = area.top() + (area.height() * i) / kGridDivY;
        double dBm = m_refLevel - i * m_dbPerDiv;
        QString label = QString::number(dBm, 'f', 0);
        QRect textRect(2, y - 8, kMarginLeft - 6, 16);
        painter.drawText(textRect, Qt::AlignRight | Qt::AlignVCenter, label);
    }

    // Axis unit labels
    painter.setPen(kColorTextDim);
    QFont unitFont("Consolas", 7);
    painter.setFont(unitFont);
    painter.drawText(QRect(2, area.top() - 16, kMarginLeft - 6, 14),
                     Qt::AlignRight | Qt::AlignBottom, "dBm");
}

// ── Info bar ──

void SpectrumPlot::drawInfoBar(QPainter& painter)
{
    const QRect area = plotArea();

    painter.fillRect(area.left(), area.top(), area.width(), 20, kColorInfoBar);

    painter.setPen(kColorAccent);
    QFont infoFont("Consolas", 8, QFont::Bold);
    painter.setFont(infoFont);

    int x = area.left() + 8;
    int y = area.top() + 2;
    int spacing = area.width() / 6;

    painter.drawText(x, y, spacing, 16, Qt::AlignLeft | Qt::AlignVCenter,
                     QString("CF: %1").arg(formatFrequency(m_centerFreq)));

    painter.drawText(x + spacing, y, spacing, 16, Qt::AlignLeft | Qt::AlignVCenter,
                     QString("Span: %1").arg(formatFrequency(m_span)));

    painter.drawText(x + spacing * 2, y, spacing, 16, Qt::AlignLeft | Qt::AlignVCenter,
                     QString("Ref: %1 dBm").arg(m_refLevel, 0, 'f', 1));

    painter.drawText(x + spacing * 3, y, spacing, 16, Qt::AlignLeft | Qt::AlignVCenter,
                     QString("%1 dB/div").arg(m_dbPerDiv, 0, 'f', 0));

    // Live stats
    painter.setPen(kColorTextDim);
    painter.drawText(x + spacing * 4, y, spacing, 16, Qt::AlignLeft | Qt::AlignVCenter,
                     QString("%1 fps").arg(m_currentFps, 0, 'f', 1));

    painter.drawText(x + spacing * 5, y, spacing - 8, 16, Qt::AlignRight | Qt::AlignVCenter,
                     QString("F#%1 D%2").arg(m_frameId).arg(m_dropCount));
}

