// ── X-Axis Labels (Frequency with Dynamic Unit Scaling) ──
painter.setFont(QFont("Consolas", 10, QFont::Bold));
painter.setPen(QColor(0xee, 0xee, 0xff)); // High contrast readable white

// Determine optimal unit for X-axis numbers based on Span
QString unitStr = "GHz";
double scaleDivider = 1.0e9;
int decimals = 3;

if (m_span < 100.0e3) {         // Span < 100 kHz -> Display numbers in kHz
    unitStr = "kHz";
    scaleDivider = 1.0e3;
    decimals = 2;
} else if (m_span < 200.0e6) {  // Span < 200 MHz -> Display numbers in MHz
    unitStr = "MHz";
    scaleDivider = 1.0e6;
    decimals = (m_span <= 10.0e6) ? 2 : 1;
} else {                       // Span >= 200 MHz -> Display numbers in GHz
    unitStr = "GHz";
    scaleDivider = 1.0e9;
    decimals = 3;
}

double startFreq = m_centerFreq - m_span / 2.0;
double freqStep  = m_span / kGridDivX;

for (int i = 0; i <= kGridDivX; ++i) {
    int x = area.left() + (area.width() * i) / kGridDivX;
    double freqVal = (startFreq + i * freqStep) / scaleDivider;
    QString label = QString("%1").arg(freqVal, 0, 'f', decimals);

    int align = Qt::AlignHCenter;
    if (i == 0) align = Qt::AlignLeft;
    else if (i == kGridDivX) align = Qt::AlignRight;

    QRect textRect(x - 50, area.bottom() + 8, 100, 20);
    painter.drawText(textRect, align | Qt::AlignTop, label);
}

// X-Axis Unit Header at Bottom Right
painter.setFont(QFont("Consolas", 10, QFont::Bold));
painter.setPen(QColor(0x00, 0xe5, 0xff));
painter.drawText(QRect(area.right() - 60, area.bottom() + 28, 60, 18),
                 Qt::AlignRight | Qt::AlignVCenter, QString("[%1]").arg(unitStr));

// X-Axis Sub-label (Center & Span)
painter.drawText(QRect(area.left(), area.bottom() + 28, area.width() - 70, 18),
                 Qt::AlignCenter, QString("CENTER: %1   |   SPAN: %2")
                                      .arg(formatFrequency(m_centerFreq))
                                      .arg(formatFrequency(m_span)));

