#ifndef RTSA_CONTROL_PANEL_H
#define RTSA_CONTROL_PANEL_H

#include "TracePipeline.h"
#include <QWidget>
#include <QPushButton>
#include <QComboBox>
#include <QDoubleSpinBox>
#include <QLabel>

namespace rtsa {

/// Unified interactive Control Panel with status header, parameters, shortcuts, and exports.
class ControlPanel : public QWidget {
    Q_OBJECT

public:
    explicit ControlPanel(QWidget* parent = nullptr);

    void setCenterFreq(double hz);
    void setSpan(double hz);
    void setRefLevel(double dBm);
    void setTraceMode(TraceMode mode);
    void setStatus(const QString& status);
    void setFps(double fps);
    void setRbw(double hz);

signals:
    void centerFreqChanged(double hz);
    void spanChanged(double hz);
    void refLevelChanged(double dBm);
    void traceModeChanged(TraceMode mode);
    void markerSelected(int markerId);
    void peakSearchRequested(int markerId);
    void nextPeakRequested(int markerId);
    void peakRightRequested(int markerId);
    void peakLeftRequested(int markerId);
    void minSearchRequested(int markerId);
    void resetTraceRequested();
    void globalDeltaToggled(bool enable, int refMarkerId);
    void clearAllMarkersRequested();
    void fullSpanRequested();
    void exportCsvRequested();
    void saveScreenshotRequested();

private:
    QString formatFrequency(double hz) const;

    // Header Live Status
    QLabel* m_statusLabel;
    QLabel* m_fpsLabel;
    QLabel* m_rbwLabel;

    // Parameter Controls
    QDoubleSpinBox* m_centerFreqSpin;
    QDoubleSpinBox* m_spanSpin;
    QDoubleSpinBox* m_refLevelSpin;
    QComboBox* m_traceModeCombo;

    // Preset & Export Buttons
    QPushButton* m_btnFullSpan;
    QPushButton* m_btnExportCsv;
    QPushButton* m_btnSaveScreenshot;

    // Marker Controls
    QComboBox* m_markerSelectCombo;
    QComboBox* m_refMarkerCombo;
    QPushButton* m_btnDeltaToggle;
    QPushButton* m_btnClearMarkers;

    QPushButton* m_btnPeakSearch;
    QPushButton* m_btnNextPeak;
    QPushButton* m_btnMinSearch;
    QPushButton* m_btnResetTrace;

    bool m_isDeltaActive = false;
};

} // namespace rtsa

#endif // RTSA_CONTROL_PANEL_H

#include "ControlPanel.h"
#include <QVBoxLayout>
#include <QHBoxLayout>
#include <QGroupBox>
#include <QPalette>
#include <QListView>

namespace rtsa {

static const QString kControlStyleSheet = R"(
    QWidget#ControlPanel {
        background-color: #1a1a2e;
    }
    QGroupBox {
        color: #4488ff;
        font-family: Consolas, monospace;
        font-size: 12px;
        font-weight: bold;
        background-color: #222238;
        border: 1px solid #3a3a55;
        border-radius: 6px;
        margin-top: 10px;
        padding-top: 12px;
    }
    QGroupBox::title {
        subcontrol-origin: margin;
        left: 12px;
        padding: 0 6px;
        background-color: #1a1a2e;
    }
    QLabel {
        color: #cccccc;
        font-family: Consolas, monospace;
        font-size: 11px;
        background-color: transparent;
    }
    QLabel#StatusHeader {
        color: #00ff88;
        font-family: Consolas, monospace;
        font-size: 13px;
        font-weight: bold;
        padding: 6px 10px;
        background-color: #121224;
        border: 1px solid #3a3a55;
        border-radius: 4px;
    }
    QLabel#ActiveMarkerInd {
        color: #00e5ff;
        font-family: Consolas, monospace;
        font-size: 12px;
        font-weight: bold;
        padding: 5px 8px;
        background-color: #121224;
        border: 1px solid #3a3a55;
        border-radius: 4px;
    }
    QDoubleSpinBox, QComboBox {
        background-color: #121224;
        color: #00ff88;
        font-family: Consolas, monospace;
        font-size: 12px;
        font-weight: bold;
        border: 1px solid #3a3a55;
        border-radius: 4px;
        padding: 5px 8px;
        min-height: 24px;
    }
    QComboBox::drop-down {
        border: none;
        width: 24px;
    }
    QComboBox QAbstractItemView {
        background-color: #121224;
        color: #00e5ff;
        font-family: Consolas, monospace;
        font-size: 12px;
        selection-background-color: #3a3a60;
        selection-color: #ffffff;
        border: 1px solid #3a3a55;
    }
    QPushButton {
        background-color: #242440;
        color: #eeeeee;
        font-family: Consolas, monospace;
        font-size: 12px;
        font-weight: bold;
        border: 1px solid #4488ff;
        border-radius: 4px;
        padding: 7px;
        min-height: 22px;
    }
    QPushButton:hover {
        background-color: #3a3a60;
        color: #ffffff;
        border-color: #00e5ff;
    }
    QPushButton:pressed {
        background-color: #4488ff;
        color: #ffffff;
    }
    QPushButton#BtnFullSpan {
        background-color: #1b3854;
        color: #00e5ff;
        border-color: #00e5ff;
    }
    QPushButton#BtnFullSpan:hover {
        background-color: #00e5ff;
        color: #101024;
    }
    QPushButton#BtnExport {
        background-color: #244030;
        color: #00ff88;
        border-color: #00ff88;
    }
    QPushButton#BtnExport:hover {
        background-color: #00ff88;
        color: #101024;
    }
)";

ControlPanel::ControlPanel(QWidget* parent)
    : QWidget(parent)
{
    setObjectName("ControlPanel");
    setAutoFillBackground(true);

    QPalette pal = palette();
    pal.setColor(QPalette::Window, QColor(0x1a, 0x1a, 0x2e));
    setPalette(pal);

    setStyleSheet(kControlStyleSheet);
    auto* mainLayout = new QVBoxLayout(this);
    mainLayout->setContentsMargins(10, 8, 10, 10);
    mainLayout->setSpacing(8);

    // ── Status Header ──
    auto* statusWidget = new QWidget(this);
    auto* statusLayout = new QHBoxLayout(statusWidget);
    statusLayout->setContentsMargins(0, 0, 0, 0);
    statusLayout->setSpacing(8);

    m_statusLabel = new QLabel("RUNNING", statusWidget);
    m_statusLabel->setObjectName("StatusHeader");

    m_fpsLabel = new QLabel("0.0 FPS", statusWidget);
    m_fpsLabel->setObjectName("StatusHeader");
    m_fpsLabel->setAlignment(Qt::AlignRight | Qt::AlignVCenter);

    statusLayout->addWidget(m_statusLabel, 1);
    statusLayout->addWidget(m_fpsLabel, 1);
    mainLayout->addWidget(statusWidget);

    // ── Group 1: Parameter Control & Shortcuts ──
    auto* paramGroup = new QGroupBox("INSTRUMENT PARAMETERS");
    auto* paramLayout = new QVBoxLayout(paramGroup);
    paramLayout->setSpacing(6);

    // Center Freq
    paramLayout->addWidget(new QLabel("Center Frequency (MHz):"));
    m_centerFreqSpin = new QDoubleSpinBox();
    m_centerFreqSpin->setRange(10.0, 6000.0);
    m_centerFreqSpin->setValue(2400.0);
    m_centerFreqSpin->setSingleStep(10.0);
    paramLayout->addWidget(m_centerFreqSpin);

    // Span & RBW row
    auto* spanHeaderLayout = new QHBoxLayout();
    spanHeaderLayout->addWidget(new QLabel("Span (MHz):"));
    m_rbwLabel = new QLabel("RBW: 24.4 kHz");
    m_rbwLabel->setStyleSheet("color: #888899; font-size: 10px; font-weight: bold;");
    m_rbwLabel->setAlignment(Qt::AlignRight | Qt::AlignVCenter);
    spanHeaderLayout->addWidget(m_rbwLabel);
    paramLayout->addLayout(spanHeaderLayout);

    m_spanSpin = new QDoubleSpinBox();
    m_spanSpin->setRange(1.0, 6000.0);
    m_spanSpin->setValue(100.0);
    m_spanSpin->setSingleStep(10.0);
    paramLayout->addWidget(m_spanSpin);

    // Full Span Preset Button
    m_btnFullSpan = new QPushButton("⚡ Full Span (10M~6GHz)");
    m_btnFullSpan->setObjectName("BtnFullSpan");
    paramLayout->addWidget(m_btnFullSpan);

    // Ref Level
    paramLayout->addWidget(new QLabel("Ref Level (dBm):"));
    m_refLevelSpin = new QDoubleSpinBox();
    m_refLevelSpin->setRange(-120.0, 30.0);
    m_refLevelSpin->setValue(0.0);
    m_refLevelSpin->setSingleStep(5.0);
    paramLayout->addWidget(m_refLevelSpin);

    mainLayout->addWidget(paramGroup);

    // ── Group 2: Trace Mode & Data Export ──
    auto* traceGroup = new QGroupBox("TRACE & DATA EXPORT");
    auto* traceLayout = new QVBoxLayout(traceGroup);
    traceLayout->setSpacing(6);

    m_traceModeCombo = new QComboBox();
    m_traceModeCombo->setView(new QListView());
    m_traceModeCombo->addItem("Clear / Write (Real-time)", static_cast<int>(TraceMode::ClearWrite));
    m_traceModeCombo->addItem("Max Hold", static_cast<int>(TraceMode::MaxHold));
    m_traceModeCombo->addItem("Min Hold", static_cast<int>(TraceMode::MinHold));
    m_traceModeCombo->addItem("Average", static_cast<int>(TraceMode::Average));
    traceLayout->addWidget(m_traceModeCombo);

    m_btnResetTrace = new QPushButton("Reset Trace");
    traceLayout->addWidget(m_btnResetTrace);

    // Export & Screenshot Buttons
    auto* expLayout = new QHBoxLayout();
    m_btnExportCsv      = new QPushButton("📊 Export CSV");
    m_btnSaveScreenshot = new QPushButton("📸 Screenshot");
    m_btnExportCsv->setObjectName("BtnExport");
    m_btnSaveScreenshot->setObjectName("BtnExport");

    expLayout->addWidget(m_btnExportCsv);
    expLayout->addWidget(m_btnSaveScreenshot);
    traceLayout->addLayout(expLayout);

    mainLayout->addWidget(traceGroup);

    // ── Group 3: Marker Controls ──
    auto* markerGroup = new QGroupBox("MARKER CONTROLS");
    auto* markerLayout = new QVBoxLayout(markerGroup);
    markerLayout->setSpacing(6);

    // Target Marker Selector
    auto* selLayout = new QHBoxLayout();
    selLayout->addWidget(new QLabel("Target:"));
    m_markerSelectCombo = new QComboBox();
    m_markerSelectCombo->setView(new QListView());
    for (int i = 1; i <= 6; ++i) {
        m_markerSelectCombo->addItem(QString("Marker %1").arg(i), i);
    }
    selLayout->addWidget(m_markerSelectCombo, 1);
    markerLayout->addLayout(selLayout);

    // Delta Reference Marker Selector
    auto* refLayout = new QHBoxLayout();
    refLayout->addWidget(new QLabel("Ref Mkr:"));
    m_refMarkerCombo = new QComboBox();
    m_refMarkerCombo->setView(new QListView());
    for (int i = 1; i <= 6; ++i) {
        m_refMarkerCombo->addItem(QString("Marker %1").arg(i), i);
    }
    m_refMarkerCombo->setCurrentIndex(0);
    refLayout->addWidget(m_refMarkerCombo, 1);
    markerLayout->addLayout(refLayout);

    // Active Marker indicator
    auto* activeInd = new QLabel("Active: Marker 1");
    activeInd->setObjectName("ActiveMarkerInd");
    markerLayout->addWidget(activeInd);

    // Action buttons
    m_btnPeakSearch = new QPushButton("Peak Search (Highest)");
    m_btnNextPeak   = new QPushButton("Next Peak (Rank Cycle)");

    auto* lrLayout = new QHBoxLayout();
    auto* btnLeft  = new QPushButton("◄ Peak Left");
    auto* btnRight = new QPushButton("Peak Right ►");
    lrLayout->addWidget(btnLeft);
    lrLayout->addWidget(btnRight);

    m_btnMinSearch  = new QPushButton("Min Search");

    auto* toolLayout = new QHBoxLayout();
    m_btnDeltaToggle  = new QPushButton("Delta Off");
    m_btnClearMarkers = new QPushButton("Clear All");
    toolLayout->addWidget(m_btnDeltaToggle);
    toolLayout->addWidget(m_btnClearMarkers);

    markerLayout->addWidget(m_btnPeakSearch);
    markerLayout->addWidget(m_btnNextPeak);
    markerLayout->addLayout(lrLayout);
    markerLayout->addWidget(m_btnMinSearch);
    markerLayout->addLayout(toolLayout);

    mainLayout->addWidget(markerGroup);
    mainLayout->addStretch();

    // Helpers
    auto currentTargetId = [this]() {
        return m_markerSelectCombo->currentIndex() + 1;
    };

    auto currentRefId = [this]() {
        return m_refMarkerCombo->currentIndex() + 1;
    };

    connect(m_markerSelectCombo, QOverload<int>::of(&QComboBox::currentIndexChanged), [this, activeInd, currentTargetId](int idx) {
        int id = idx + 1;
        activeInd->setText(QString("Active: Marker %1").arg(id));
        emit markerSelected(id);
    });

    connect(m_refMarkerCombo, QOverload<int>::of(&QComboBox::currentIndexChanged), [this, currentRefId](int) {
        if (m_isDeltaActive) {
            emit globalDeltaToggled(true, currentRefId());
        }
    });

    connect(m_btnPeakSearch, &QPushButton::clicked, [this, currentTargetId]() {
        emit peakSearchRequested(currentTargetId());
    });
    connect(m_btnNextPeak, &QPushButton::clicked, [this, currentTargetId]() {
        emit nextPeakRequested(currentTargetId());
    });
    connect(btnLeft, &QPushButton::clicked, [this, currentTargetId]() {
        emit peakLeftRequested(currentTargetId());
    });
    connect(btnRight, &QPushButton::clicked, [this, currentTargetId]() {
        emit peakRightRequested(currentTargetId());
    });
    connect(m_btnMinSearch, &QPushButton::clicked, [this, currentTargetId]() {
        emit minSearchRequested(currentTargetId());
    });

    connect(m_btnDeltaToggle, &QPushButton::clicked, [this, currentRefId]() {
        m_isDeltaActive = !m_isDeltaActive;
        if (m_isDeltaActive) {
            m_btnDeltaToggle->setText("Delta ON");
            m_btnDeltaToggle->setStyleSheet("background-color: #00ff88; color: #101024;");
        } else {
            m_btnDeltaToggle->setText("Delta Off");
            m_btnDeltaToggle->setStyleSheet("");
        }
        emit globalDeltaToggled(m_isDeltaActive, currentRefId());
    });

    connect(m_btnClearMarkers, &QPushButton::clicked, [this]() {
        m_isDeltaActive = false;
        m_btnDeltaToggle->setText("Delta Off");
        m_btnDeltaToggle->setStyleSheet("");
        emit globalDeltaToggled(false, 1);
        emit clearAllMarkersRequested();
    });

    // ── Shortcuts & Exports Connections ──
    connect(m_btnFullSpan, &QPushButton::clicked, this, &ControlPanel::fullSpanRequested);
    connect(m_btnExportCsv, &QPushButton::clicked, this, &ControlPanel::exportCsvRequested);
    connect(m_btnSaveScreenshot, &QPushButton::clicked, this, &ControlPanel::saveScreenshotRequested);

    // ── Parameter Connections ──
    connect(m_centerFreqSpin, QOverload<double>::of(&QDoubleSpinBox::valueChanged), [this](double valMHz) {
        emit centerFreqChanged(valMHz * 1e6);
    });

    connect(m_spanSpin, QOverload<double>::of(&QDoubleSpinBox::valueChanged), [this](double valMHz) {
        emit spanChanged(valMHz * 1e6);
    });

    connect(m_refLevelSpin, QOverload<double>::of(&QDoubleSpinBox::valueChanged), [this](double valdBm) {
        emit refLevelChanged(valdBm);
    });

    connect(m_traceModeCombo, QOverload<int>::of(&QComboBox::currentIndexChanged), [this](int idx) {
        auto mode = static_cast<TraceMode>(m_traceModeCombo->itemData(idx).toInt());
        emit traceModeChanged(mode);
    });

    connect(m_btnResetTrace, &QPushButton::clicked, this, &ControlPanel::resetTraceRequested);
}

void ControlPanel::setCenterFreq(double hz)
{
    m_centerFreqSpin->blockSignals(true);
    m_centerFreqSpin->setValue(hz / 1e6);
    m_centerFreqSpin->blockSignals(false);
}

void ControlPanel::setSpan(double hz)
{
    m_spanSpin->blockSignals(true);
    m_spanSpin->setValue(hz / 1e6);
    m_spanSpin->blockSignals(false);
}

void ControlPanel::setRefLevel(double dBm)
{
    m_refLevelSpin->blockSignals(true);
    m_refLevelSpin->setValue(dBm);
    m_refLevelSpin->blockSignals(false);
}

void ControlPanel::setTraceMode(TraceMode mode)
{
    m_traceModeCombo->blockSignals(true);
    int idx = m_traceModeCombo->findData(static_cast<int>(mode));
    if (idx != -1) m_traceModeCombo->setCurrentIndex(idx);
    m_traceModeCombo->blockSignals(false);
}

void ControlPanel::setStatus(const QString& status)
{
    m_statusLabel->setText(status);
}

void ControlPanel::setFps(double fps)
{
    m_fpsLabel->setText(QString("%1 FPS").arg(fps, 0, 'f', 1));
}

void ControlPanel::setRbw(double hz)
{
    m_rbwLabel->setText("RBW: " + formatFrequency(hz));
}

QString ControlPanel::formatFrequency(double hz) const
{
    if (hz >= 1e9) return QString("%1 GHz").arg(hz / 1e9, 0, 'f', 3);
    if (hz >= 1e6) return QString("%1 MHz").arg(hz / 1e6, 0, 'f', 2);
    if (hz >= 1e3) return QString("%1 kHz").arg(hz / 1e3, 0, 'f', 1);
    return QString("%1 Hz").arg(hz, 0, 'f', 0);
}

} // namespace rtsa

