QObject::connect(controlPanel, &rtsa::ControlPanel::traceModeChanged, [=](rtsa::TraceMode mode) {
    dataProcessor->setTraceMode(mode);
});

// ── Full Span Shortcut ──
QObject::connect(controlPanel, &rtsa::ControlPanel::fullSpanRequested, [=]() {
    double fullCenter = 3005.0e6; // 3.005 GHz
    double fullSpan   = 5990.0e6; // 5.990 GHz (10MHz ~ 6000MHz)

    paramTxn->setCenterFreq(fullCenter);
    paramTxn->setSpan(fullSpan);
    if (paramTxn->commit()) {
        spectrumPlot->setCenterFreq(fullCenter);
        spectrumPlot->setSpan(fullSpan);
        controlPanel->setCenterFreq(fullCenter);
        controlPanel->setSpan(fullSpan);
        controlPanel->setRbw(fullSpan / 4096);
        dataProcessor->setParams(fullCenter, fullSpan);
        rtsa::Logger::info("Main", "Full Span set: 10 MHz to 6.0 GHz");
    }
});

// ── Screenshot Archiving ──
QObject::connect(controlPanel, &rtsa::ControlPanel::saveScreenshotRequested, [&window]() {
    QDir exportDir("exports");
    if (!exportDir.exists()) {
        QDir().mkdir("exports");
    }
    QString timestamp = QDateTime::currentDateTime().toString("yyyyMMdd_hhmmss");
    QString filename = QString("exports/screenshot_%1.png").arg(timestamp);

    QPixmap pixmap = window.grab();
    if (pixmap.save(filename)) {
        rtsa::Logger::info("Main", QString("Screenshot saved to %1").arg(filename).toStdString());
    } else {
        rtsa::Logger::error("Main", "Failed to save screenshot");
    }
});

// ── CSV Data Export ──
QObject::connect(controlPanel, &rtsa::ControlPanel::exportCsvRequested, [dataProcessor, spectrumPlot]() {
    QDir exportDir("exports");
    if (!exportDir.exists()) {
        QDir().mkdir("exports");
    }
    QString timestamp = QDateTime::currentDateTime().toString("yyyyMMdd_hhmmss");
    QString filename = QString("exports/trace_%1.csv").arg(timestamp);

    QFile file(filename);
    if (file.open(QIODevice::WriteOnly | QIODevice::Text)) {
        QTextStream out(&file);
        out << "Frequency_Hz,Amplitude_dBm\n";

        double centerFreq = spectrumPlot->centerFreq();
        double span = spectrumPlot->span();
        double startFreq = centerFreq - span / 2.0;

        const auto& processeddBm = dataProcessor->processedFrame().dBm;
        int count = static_cast<int>(processeddBm.size());

        if (count > 0) {
            for (int i = 0; i < count; ++i) {
                double freq = startFreq + (static_cast<double>(i) / count) * span;
                out << QString::number(freq, 'f', 2) << ","
                    << QString::number(processeddBm[i], 'f', 2) << "\n";
            }
        }

        file.close();
        rtsa::Logger::info("Main", QString("Trace CSV exported to %1 (%2 points)")
                                       .arg(filename)
                                       .arg(count)
                                       .toStdString());
    } else {
        rtsa::Logger::error("Main", "Failed to create CSV export file");
    }
});

