#include "ParamTransaction.h"
#include "Logger.h"
#include <algorithm>

namespace rtsa {

static const char* TAG = "ParamTxn";

ParamTransaction::ParamTransaction(IHalInterface* hal)
    : m_hal(hal)
{
}

void ParamTransaction::setCenterFreq(double hz)
{
    m_pendingCenterFreq = hz;
    m_dirtyCenterFreq = true;
}

void ParamTransaction::setSpan(double hz)
{
    m_pendingSpan = hz;
    m_dirtySpan = true;
}

void ParamTransaction::setRefLevel(double dBm)
{
    m_pendingRefLevel = dBm;
    m_dirtyRefLevel = true;
}

void ParamTransaction::setDbPerDiv(double db)
{
    m_pendingDbPerDiv = db;
    m_dirtyDbPerDiv = true;
}

bool ParamTransaction::validate(QString& errorReason)
{
    // Bounds check for 10 MHz ~ 6 GHz RF range
    if (m_dirtyCenterFreq && (m_pendingCenterFreq < 10e6 || m_pendingCenterFreq > 6.0e9)) {
        errorReason = "Center Frequency must be between 10 MHz and 6 GHz";
        return false;
    }

    if (m_dirtySpan && (m_pendingSpan < 1e3 || m_pendingSpan > 6.0e9)) {
        errorReason = "Span must be between 1 kHz and 6.0 GHz";
        return false;
    }

    if (m_dirtyRefLevel && (m_pendingRefLevel < -120.0 || m_pendingRefLevel > 30.0)) {
        errorReason = "Ref Level must be between -120 dBm and +30 dBm";
        return false;
    }

    if (m_dirtyDbPerDiv && (m_pendingDbPerDiv < 1.0 || m_pendingDbPerDiv > 20.0)) {
        errorReason = "dB/div must be between 1 dB and 20 dB";
        return false;
    }

    // Coupled check
    double center = m_dirtyCenterFreq ? m_pendingCenterFreq : m_hal->centerFreq();
    double span   = m_dirtySpan ? m_pendingSpan : m_hal->span();

    double startFreq = center - span / 2.0;
    double stopFreq  = center + span / 2.0;

    if (startFreq < 0.0 || stopFreq > 6.05e9) {
        errorReason = QString("Frequency range [%1, %2] MHz exceeds 0 ~ 6050 MHz hardware limit")
                          .arg(startFreq / 1e6, 0, 'f', 1)
                          .arg(stopFreq / 1e6, 0, 'f', 1);
        return false;
    }

    return true;
}

bool ParamTransaction::commit()
{
    QString error;
    if (!validate(error)) {
        Logger::error(TAG, "Validation failed: " + error);
        return false;
    }

    if (!m_hal) {
        Logger::error(TAG, "HAL interface is null");
        return false;
    }

    bool success = true;

    if (m_dirtyCenterFreq) {
        success &= m_hal->setCenterFreq(m_pendingCenterFreq);
    }
    if (m_dirtySpan) {
        success &= m_hal->setSpan(m_pendingSpan);
    }
    if (m_dirtyRefLevel) {
        success &= m_hal->setRefLevel(m_pendingRefLevel);
    }
    if (m_dirtyDbPerDiv) {
        success &= m_hal->setDbPerDiv(m_pendingDbPerDiv);
    }

    if (success) {
        clearFlags();
        Logger::info(TAG, "Transaction committed successfully");
    } else {
        Logger::error(TAG, "HAL failed to write registers");
    }

    return success;
}

void ParamTransaction::rollback()
{
    clearFlags();
    Logger::info(TAG, "Transaction rolled back");
}

void ParamTransaction::clearFlags()
{
    m_dirtyCenterFreq = false;
    m_dirtySpan = false;
    m_dirtyRefLevel = false;
    m_dirtyDbPerDiv = false;
}

} // namespace rtsa

