88: void DataProcessor::run()
89: {
90:     Logger::info(TAG, QString("Thread started (fftSize=%1, interval=16ms)").arg(m_fftSize));
91:     m_running = true;
92: 
93:     QTimer timer;
94:     timer.setTimerType(Qt::PreciseTimer); // Use precise timer
95:     connect(&timer, &QTimer::timeout, [this]() {
96:         if (!m_running) return;
97: 
98:         if (m_buffer->consume()) {
99:             const SpectrumFrame& frame = m_buffer->getReadBuffer();
100:             processFrame(frame);
101:         }
102:     });
103:     timer.start(16);
104: 
105:     exec();
106: 
107:     Logger::info(TAG, QString("Thread stopped. Processed: %1, Dropped: %2")
108:                           .arg(m_processedCount)
109:                           .arg(m_dropCount));
110: }
111: 
112: void DataProcessor::processFrame(const SpectrumFrame& raw)
113: {
114:     std::lock_guard<std::mutex> lock(m_mutex);
115: 
116:     // Detect dropped frames
117:     if (m_lastFrameId > 0 && raw.frameId > m_lastFrameId + 1) {
118:         uint64_t dropped = raw.frameId - m_lastFrameId - 1;
119:         m_dropCount += dropped;
120:     }
121:     m_lastFrameId = raw.frameId;
122: 
123:     int count = std::min(raw.size, m_fftSize);
124: 
125:     // Step 1: TracePipeline processing (ClearWrite, MaxHold, MinHold, Average)
126:     m_tracePipeline.process(raw.data.data(), count, m_processeddBm);
127: 
128:     // Step 2: Marker triggers
129:     if (m_pendingPeakSearch) {
130:         m_markerEngine.searchPeak(m_searchMarkerId, m_processeddBm.data(), count, m_centerFreqHz, m_spanHz);
131:         m_pendingPeakSearch = false;
132:     }
133:     if (m_pendingNextPeak) {
134:         m_markerEngine.searchNextPeak(m_searchMarkerId, m_processeddBm.data(), count, m_centerFreqHz, m_spanHz);
135:         m_pendingNextPeak = false;
136:     }
137:     if (m_pendingNextPeakRight) {
138:         m_markerEngine.searchNextPeakRight(m_searchMarkerId, m_processeddBm.data(), count, m_centerFreqHz, m_spanHz);
139:         m_pendingNextPeakRight = false;
140:     }
141:     if (m_pendingNextPeakLeft) {
142:         m_markerEngine.searchNextPeakLeft(m_searchMarkerId, m_processeddBm.data(), count, m_centerFreqHz, m_spanHz);
143:         m_pendingNextPeakLeft = false;
144:     }
145:     if (m_pendingMinSearch) {
146:         m_markerEngine.searchMin(m_searchMarkerId, m_processeddBm.data(), count, m_centerFreqHz, m_spanHz);
147:         m_pendingMinSearch = false;
148:     }
149: 
150:     // Step 3: Update existing markers
151:     m_markerEngine.updateMarkers(m_processeddBm.data(), count, m_centerFreqHz, m_spanHz);
152: 
153:     // Step 4: Min-Max Pixel Decimation (Compress 4096 points -> 800 pixel buckets * 2 = 1600 points)
154:     static std::vector<float> decimateddBm;
155:     const int targetPixels = 800;
156:     TraceDecimator::decimateMinMax(m_processeddBm.data(), count, targetPixels, decimateddBm);
157: 
158:     // Step 5: Prepare ProcessedFrame
159:     ProcessedFrame result;
160:     result.frameId   = raw.frameId;
161:     result.dropCount = m_dropCount;
162: #if QT_VERSION >= QT_VERSION_CHECK(6, 0, 0)
163:     result.dBm.assign(decimateddBm.begin(), decimateddBm.end());
164: #else
165:     result.dBm = QVector<float>::fromStdVector(decimateddBm);
166: #endif
167: 
168:     m_processedCount++;
169: 
170:     emit frameReady(result);
171:     emit markersUpdated();
172: }
